// sprintfBinding is a String binding that formats multiple source values using a format string
type sprintfBinding struct {
	base

	format  string
	sources []DataItem
	mu      sync.RWMutex
}

// Get returns the formatted string value
func (s *sprintfBinding) Get() (string, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		val, err := source.(String).Get()
		if err != nil {
			return "", err
		}
		values[i] = val
	}

	return fmt.Sprintf(s.format, values...), nil
}

// Set is not supported for sprintf bindings as they are read-only
func (s *sprintfBinding) Set(string) error {
	return fmt.Errorf("sprintf binding is read-only")
}

// AddListener attaches a new change listener to this binding
func (s *sprintfBinding) AddListener(listener DataListener) {
	s.mu.Lock()
	defer s.mu.Unlock()

	s.base.AddListener(listener)

	// Listen to all source bindings
	for _, source := range s.sources {
		source.AddListener(NewDataListener(func() {
			s.trigger()
		}))
	}
}

// RemoveListener detaches the specified listener
func (s *sprintfBinding) RemoveListener(listener DataListener) {
	s.base.RemoveListener(listener)
}

func (s *sprintfBinding) trigger() {
	s.lock.RLock()
	items := s.listeners
	s.lock.RUnlock()

	for _, item := range items {
		item.DataChanged()
	}
}

